import React from 'react';
import'./Signup.css';

function Signup() {
  return (
    <div className="signupContainer">
      <form className="signupForm montserratFont">
        <h2>Sign Up</h2>
        <div className="textField">
          <input className="montserratFont" type="text" placeholder="User Name" />
        </div>
        <div className="textField">
          <input className="montserratFont" type="email" placeholder="Email" />
        </div>
        <div className="textField">
          <input className="montserratFont" type="password" placeholder="Password" />
        </div>
        <button className="signupButton" type="submit">Sign Up</button>
      </form>
      <p>
        Already have an account? <a href="/signin">Sign In</a>
      </p>
    </div>
  );
}

export default Signup;
